const PRODUCTS={cleanser:{name:"CeraVe Foaming Cleanser",img:"data:image/png;base64,",fallback:"cleanser"},vitc:{name:"Garnier Vitamin C Serum",img:"data:image/png;base64,",fallback:"vitc"},niacinamide:{name:"The Ordinary Niacinamide",img:"data:image/png;base64,",fallback:"niacinamide"},azelaic:{name:"The Ordinary Azelaic Acid",img:"data:image/png;base64,",fallback:"azelaic"},moisturizer:{name:"CeraVe Moisturizing Lotion",img:"data:image/png;base64,",fallback:"moisturizer"},spf:{name:"La Roche-Posay SPF50+",img:"data:image/png;base64,",fallback:"spf"}};
const AZELAIC_DAYS=[3,6,10,13,17,20,24,27,30],STORAGE_KEY='skinRoutineState',PHOTO_DB='skinRoutinePhotosV3',PHOTO_STORE='photos';
const iso=()=>new Date().toISOString().slice(0,10),dObj=s=>new Date(s+'T00:00:00');
function def(){return{startDate:iso(),completed:{},morningTime:'08:00',nightTime:'22:00',theme:'light',photoDays:{},notifications:false,lastReminder:{}}}
function migrate(c){const out={};for(const[k,a0]of Object.entries(c||{})){const day=k.replace(/^day-/,'');const a=Array.isArray(a0)?a0:[],n=new Set();for(const id of a){const map={cleanser:'morning-cleanser',moisturizer:'morning-moisturizer',vitc:'morning-vitc',spf:'morning-spf',niacinamide:'night-niacinamide',azelaic:'night-azelaic'};n.add(map[id]||id)}out['day-'+day]=[...n]}return out}
function load(){try{const s=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(!s)return def();return{...def(),...s,completed:migrate(s.completed),photoDays:s.photoDays||{}}}catch{return def()}}
let state=load(),currentTab='today',previewDay=null,deferredInstall=null,photoTarget=null,urls={},timer=null,touchX=0;
const save=()=>localStorage.setItem(STORAGE_KEY,JSON.stringify(state));
const currentDay=()=>Math.max(1,Math.min(30,Math.floor((dObj(iso())-dObj(state.startDate))/86400000)+1));
const az=d=>AZELAIC_DAYS.includes(d);
const routine=d=>({morning:[['morning-cleanser','Cleanser','cleanser','Gentle cleanse'],['morning-vitc','Vitamin C','vitc','Brightening serum'],['morning-moisturizer','Moisturizer','moisturizer','Barrier moisture'],['morning-spf','SPF 50+','spf','Sun protection']],night:[['night-cleanser','Cleanser','cleanser','Gentle cleanse'],[az(d)?'night-azelaic':'night-niacinamide',az(d)?'Azelaic Acid':'Niacinamide',az(d)?'azelaic':'niacinamide',az(d)?'Selected night':'Normal night'],['night-moisturizer','Moisturizer','moisturizer','Barrier moisture']]});
const doneSet=d=>new Set(state.completed['day-'+d]||[]);
function toggle(day,id){const k='day-'+day,s=doneSet(day);s.has(id)?s.delete(id):s.add(id);state.completed[k]=[...s];save();render('today')}
const all=d=>[...routine(d).morning,...routine(d).night],pct=d=>Math.round(doneSet(d).size/all(d).length*100),completedDays=()=>Array.from({length:30},(_,i)=>pct(i+1)===100).filter(Boolean).length;
function streak(){let n=0;for(let d=Math.min(30,currentDay());d>=1&&pct(d)===100;d--)n++;return n}
function planDate(d){const x=dObj(state.startDate);x.setDate(x.getDate()+d-1);return x.toLocaleDateString('en-GB',{day:'2-digit',month:'short'})}
function imgTag(key,cls='task-img'){const p=PRODUCTS[key];return `<span class="${cls}"><img src="${p.img}" alt="" data-product-img="${key}"></span>`}
function task(d,id,label,key,sub){const yes=doneSet(d).has(id);return `<button type="button" class="task ${yes?'done':''}" data-day="${d}" data-id="${id}"><span class="tick">${yes?'✓':''}</span>${imgTag(key)}<span class="task-copy"><b>${label}</b><small>${sub}</small></span></button>`}
function repairImages(){document.querySelectorAll('[data-product-img]').forEach(img=>{img.onerror=()=>{img.onerror=null;const k=img.dataset.productImg;const label=k==='spf'?'SPF':k.toUpperCase().slice(0,6);const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100"><rect width="100" height="100" rx="16" fill="#eeeae2"/><rect x="37" y="12" width="26" height="72" rx="7" fill="#fff" stroke="#c9c1b4"/><text x="50" y="55" text-anchor="middle" font-family="Arial" font-size="9" fill="#5f6d57">${label}</text></svg>`;img.src='data:image/svg+xml;charset=UTF-8,'+encodeURIComponent(svg)}})}
function today(){const d=previewDay||currentDay(),r=routine(d),ds=doneSet(d),m=r.morning.filter(x=>ds.has(x[0])).length,n=r.night.filter(x=>ds.has(x[0])).length,p=pct(d);return `<div class="home" id="home"><header class="home-head"><div><div class="eyebrow">${previewDay?'PLAN PREVIEW':'TODAY'}</div><h2>${previewDay?'Day '+d:'Good day'} <span>· ${planDate(d)}</span></h2><p>${p===100?'All done — great job! 🎉':p>0?'Keep going. You are on track.':'One simple step at a time.'}</p></div><div class="day-ring"><strong>${d}</strong><small>/30</small></div></header><div class="day-nav"><button type="button" id="prevDay" aria-label="Previous day">‹</button><div class="day-label">${d===currentDay()&&!previewDay?'Today':'Day '+d} · swipe for next/previous</div><button type="button" id="nextDay" aria-label="Next day">›</button></div><section class="progress-strip"><div><strong>${p}%</strong><small>today</small></div><div class="progress-line"><i style="width:${p}%"></i></div><div class="stat"><strong>${streak()}</strong><small>streak</small></div></section><section class="routine-grid"><div class="routine-card morning"><div class="routine-head"><span class="routine-icon">☀️</span><div><b>Morning</b><small>${m}/4 complete</small></div></div>${r.morning.map(x=>task(d,...x)).join('')}</div><div class="routine-card night"><div class="routine-head"><span class="routine-icon">🌙</span><div><b>Night</b><small>${n}/3 · ${az(d)?'Azelaic night':'Niacinamide night'}</small></div></div>${r.night.map(x=>task(d,...x)).join('')}</div></section><div class="swipe-hint">← previous day &nbsp; • &nbsp; next day →</div></div>`}
function moveDay(delta){let d=previewDay||currentDay();d=Math.max(1,Math.min(30,d+delta));previewDay=d===currentDay()?null:d;render('today')}
function days(){const cd=currentDay();return `<div class="tab"><header><div><div class="eyebrow">YOUR PLAN</div><h2>30 Days</h2><p>Tap any day to preview its routine.</p></div><span class="chip">${completedDays()}/30 done</span></header><div class="days-grid">${Array.from({length:30},(_,i)=>{const n=i+1,p=pct(n);return `<button type="button" class="day-card ${p===100?'done':''} ${n===cd?'today':''}" data-preview="${n}"><strong>${n}</strong><small>${p===100?'✓':p+'%'}</small></button>`}).join('')}</div><div class="tab-note">🌙 Azelaic nights: ${AZELAIC_DAYS.join(', ')} · other nights use Niacinamide.</div></div>`}
function photoCard(d){const has=!!state.photoDays[d];return `<div class="photo-card"><div class="photo-box" id="photo-${d}">${has?'Loading…':'Day '+d}</div><button type="button" class="photo-btn" data-photo="${d}">${has?'Replace photo':'Add photo'}</button>${has?`<button type="button" class="remove-btn" data-remove-photo="${d}">Remove</button>`:''}</div>`}
function progress(){const cd=completedDays(),p=Math.round(cd/30*100);return `<div class="tab progress-tab"><header><div><div class="eyebrow">YOUR PROGRESS</div><h2>Progress</h2><p>Keep your routine consistent.</p></div><span class="chip">${p}%</span></header><section class="progress-card"><div class="big-number"><strong>${cd}</strong><small>/30 days</small></div><div><b>Completed days</b><small>🔥 ${streak()} day streak</small></div><div class="progress-line wide"><i style="width:${p}%"></i></div></section><div class="photo-title"><b>📸 Progress photos</b><small>Day 1 · 15 · 30</small></div><div class="photos">${[1,15,30].map(photoCard).join('')}</div><div class="tab-note">Use similar lighting, distance and angle for a fair visual comparison.</div></div>`}
async function render(tab=currentTab){if(tab)currentTab=tab;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.tab===currentTab));const s=document.getElementById('screen');s.innerHTML=currentTab==='today'?today():currentTab==='days'?days():progress();applyTheme();repairImages();if(currentTab==='progress')await hydratePhotos()}
function applyTheme(){document.documentElement.dataset.theme=state.theme||'light';updateTheme()}
function updateTheme(){const b=document.getElementById('themeBtn');if(b)b.textContent='🌙 Dark mode: '+(state.theme==='dark'?'ON':'OFF')}
function openSettings(){document.getElementById('startDate').value=state.startDate;document.getElementById('morningTime').value=state.morningTime;document.getElementById('nightTime').value=state.nightTime;updateTheme();updateNotifyStatus();document.getElementById('modal').classList.remove('hidden')}
function closeSettings(){document.getElementById('modal').classList.add('hidden')}
function updateNotifyStatus(){const el=document.getElementById('notifyStatus'),btn=document.getElementById('notifyBtn');if(!('Notification'in window)){el.textContent='Notifications are not supported here';btn.textContent='🔔 Not supported';return}const p=Notification.permission;el.textContent=p==='granted'?'Notifications: ON ✓ — tap Test to verify':p==='denied'?'Notifications: BLOCKED — allow this site in Chrome settings':'Notifications: not enabled';btn.textContent=p==='granted'?'🔔 Test notification':'🔔 Enable & Test notification'}
async function testNotification(){if(!('Notification'in window)){alert('Chrome/Samsung Internet notification support is required.');return}if(Notification.permission==='denied'){alert('Notifications are blocked for this site. In Chrome: Site info → Permissions → Notifications → Allow.');return}const p=Notification.permission==='granted'?'granted':await Notification.requestPermission();if(p!=='granted'){updateNotifyStatus();alert('Notification permission was not granted.');return}try{const reg=await navigator.serviceWorker.ready;await reg.showNotification('Skin Routine ✓',{body:'Test successful — this notification came from your Skin Routine app.',icon:'./icons/icon-192.png',badge:'./icons/icon-192.png',tag:'skin-test-v7',renotify:true});state.notifications=true;save();updateNotifyStatus()}catch(e){alert('Test notification failed. Please open the app from the HTTPS GitHub Pages URL and allow Notifications for this site.')} }
function nextReminder(){const now=new Date(),arr=[];for(const[label,t]of[['Morning',state.morningTime],['Night',state.nightTime]]){const[h,m]=t.split(':').map(Number),x=new Date(now);x.setHours(h,m,0,0);if(x<=now)x.setDate(x.getDate()+1);arr.push([x,label])}arr.sort((a,b)=>a[0]-b[0]);return arr[0]}
function scheduleNext(){clearTimeout(timer);if(Notification.permission!=='granted')return;const[when,label]=nextReminder();timer=setTimeout(async()=>{try{const reg=await navigator.serviceWorker.ready;await reg.showNotification(label+' skincare',{body:'Time for your '+label.toLowerCase()+' routine.',icon:'./icons/icon-192.png',badge:'./icons/icon-192.png',tag:'skin-'+label.toLowerCase(),renotify:true})}catch{}scheduleNext()},Math.max(1000,when-Date.now()))}
function checkMissed(){if(Notification.permission!=='granted')return;const now=new Date();const todayKey=iso();for(const[label,t]of[['Morning',state.morningTime],['Night',state.nightTime]]){const[h,m]=t.split(':').map(Number);const stamp=todayKey+'-'+label;if(now.getHours()>h||now.getHours()===h&&now.getMinutes()>=m){if(state.lastReminder[stamp])continue;state.lastReminder[stamp]=Date.now();save();if((label==='Morning'&&pct(currentDay())<40)||(label==='Night'&&pct(currentDay())<100)){navigator.serviceWorker.ready.then(reg=>reg.showNotification(label+' skincare reminder',{body:'Your '+label.toLowerCase()+' routine is waiting for you.',icon:'./icons/icon-192.png',badge:'./icons/icon-192.png',tag:'missed-'+label.toLowerCase()})).catch(()=>{})}}}}
async function openDB(){return new Promise((res,rej)=>{const q=indexedDB.open(PHOTO_DB,1);q.onupgradeneeded=()=>q.result.createObjectStore(PHOTO_STORE);q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)})}async function putPhoto(d,b){const db=await openDB();return new Promise((res,rej)=>{const t=db.transaction(PHOTO_STORE,'readwrite');t.objectStore(PHOTO_STORE).put(b,String(d));t.oncomplete=()=>{db.close();res()};t.onerror=()=>rej(t.error)})}async function getPhoto(d){const db=await openDB();return new Promise((res,rej)=>{const q=db.transaction(PHOTO_STORE).objectStore(PHOTO_STORE).get(String(d));q.onsuccess=()=>{db.close();res(q.result)};q.onerror=()=>rej(q.error)})}async function delPhoto(d){const db=await openDB();return new Promise((res,rej)=>{const t=db.transaction(PHOTO_STORE,'readwrite');t.objectStore(PHOTO_STORE).delete(String(d));t.oncomplete=()=>{db.close();res()};t.onerror=()=>rej(t.error)})}async function hydratePhotos(){for(const d of[1,15,30])if(state.photoDays[d]){try{const b=await getPhoto(d),box=document.getElementById('photo-'+d);if(b&&box){if(urls[d])URL.revokeObjectURL(urls[d]);urls[d]=URL.createObjectURL(b);box.innerHTML=`<img src="${urls[d]}" alt="Day ${d}">`}}catch{}}}async function removePhoto(d){await delPhoto(d).catch(()=>{});delete state.photoDays[d];save();render('progress')}function choosePhoto(d){photoTarget=d;const i=document.getElementById('photoInput');i.value='';i.click()}function compress(f){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const max=1200,s=Math.min(1,max/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*s);c.height=Math.round(im.height*s);c.getContext('2d').drawImage(im,0,0,c.width,c.height);c.toBlob(b=>b?res(b):rej(), 'image/jpeg',.82)};im.onerror=rej;im.src=r.result};r.onerror=rej;r.readAsDataURL(f)})}
const input=document.getElementById('photoInput');input.onchange=async e=>{const f=e.target.files?.[0];if(!f||!photoTarget)return;try{await putPhoto(photoTarget,await compress(f));state.photoDays[photoTarget]=true;save();render('progress')}catch{alert('Photo save failed. Please try another image.')}};
const screen=document.getElementById('screen');screen.addEventListener('click',e=>{const t=e.target.closest('[data-id]');if(t){toggle(Number(t.dataset.day),t.dataset.id);return}const day=e.target.closest('[data-preview]');if(day){previewDay=Number(day.dataset.preview);render('today');return}const photo=e.target.closest('[data-photo]');if(photo){choosePhoto(Number(photo.dataset.photo));return}const rem=e.target.closest('[data-remove-photo]');if(rem){removePhoto(Number(rem.dataset.removePhoto));return}if(e.target.closest('#prevDay'))moveDay(-1);if(e.target.closest('#nextDay'))moveDay(1)});
screen.addEventListener('touchstart',e=>{touchX=e.changedTouches[0].clientX},{passive:true});screen.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-touchX;if(currentTab==='today'&&Math.abs(dx)>60)moveDay(dx<0?1:-1)},{passive:true});
document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>{previewDay=null;render(b.dataset.tab)});document.getElementById('settingsBtn').onclick=openSettings;document.getElementById('closeModal').onclick=closeSettings;document.getElementById('startDate').onchange=e=>{state.startDate=e.target.value;save();previewDay=null;render('today')};document.getElementById('morningTime').onchange=e=>{state.morningTime=e.target.value;save();scheduleNext()};document.getElementById('nightTime').onchange=e=>{state.nightTime=e.target.value;save();scheduleNext()};document.getElementById('themeBtn').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';save();applyTheme()};document.getElementById('notifyBtn').onclick=testNotification;document.getElementById('installBtn').onclick=async()=>{if(deferredInstall){deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null}else alert('Chrome menu → Install app / Add to Home screen ഉപയോഗിക്കുക.')};document.getElementById('resetBtn').onclick=async()=>{if(confirm('Reset routine progress and photos?')){for(const d of[1,15,30])await delPhoto(d).catch(()=>{});const keep={startDate:state.startDate,morningTime:state.morningTime,nightTime:state.nightTime,theme:state.theme};state={...def(),...keep};save();closeSettings();render('today')}};window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e});window.addEventListener('focus',()=>{scheduleNext();checkMissed()});
if('serviceWorker'in navigator)window.addEventListener('load',async()=>{try{const regs=await navigator.serviceWorker.getRegistrations();for(const r of regs)await r.update();await navigator.serviceWorker.register('service-worker.js?v=8',{scope:'./'});const reg=await navigator.serviceWorker.ready;reg.update();}catch{}});
applyTheme();render('today');scheduleNext();checkMissed();
